const $=(q,r=document)=>r.querySelector(q),$$=(q,r=document)=>[...r.querySelectorAll(q)];
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('ru-RU',{style:'currency',currency:'RUB',maximumFractionDigits:0}).format(n??0);
const date=x=>x?new Date(x+'T12:00:00Z').toLocaleDateString('ru-RU',{day:'numeric',month:'short'}):'—';
const stamp=x=>new Date(x).toLocaleString('ru-RU',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'});
const plus=(v,n)=>new Date(Date.parse(v+'T00:00:00Z')+n*86400000).toISOString().slice(0,10);
const icons={home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',search:'m21 21-5-5M19 10a9 9 0 1 1-18 0 9 9 0 0 1 18 0Z',bed:'M3 18v3m18-3v3M3 14V5m18 9V8H9v6M3 18h18v-4H3ZM5 8h2v3H5Z',calendar:'M8 2v4m8-4v4M3 10h18M4 4h16v17H4Z',people:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m18 0v-2a4 4 0 0 0-3-4M13 3a4 4 0 0 1 0 8M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0Z',check:'m5 12 4 4L19 6',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9m-8 12h4',chart:'M3 3v18h18M7 16v-4m5 4V7m5 9v-7',shield:'M12 2 3 6v6c0 5 9 10 9 10s9-5 9-10V6Z',settings:'M12 8a4 4 0 1 1 0 8 4 4 0 0 1 0-8Zm0-6v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2',help:'M9 9a3 3 0 1 1 5 2c-2 1-2 2-2 3m0 3v1M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z',logout:'M10 3H3v18h7m4-14 5 5-5 5m-7-5h14',moon:'M21 13a9 9 0 0 1-10-10 9 9 0 1 0 10 10Z',sun:'M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1 1m12 12 1 1M5 19l1-1M18 6l1-1M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0Z',menu:'M3 6h18M3 12h18M3 18h18',arrow:'m12 5-7 7 7 7M5 12h16',refresh:'M20 4v6h-6M4 20v-6h6M4 9a8 8 0 0 1 14-5m2 11a8 8 0 0 1-14 5',plus:'M12 5v14M5 12h14',close:'m6 6 12 12M6 18 18 6',file:'M14 2H4v20h16V8Zm0 0v6h6M8 13h8m-8 4h8',card:'M2 7h20M3 3h18v17H3Zm3 12h5',camera:'M4 6h4l2-3h4l2 3h4v15H4Zm12 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0Z',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Zm13 0a3 3 0 1 1-6 0 3 3 0 0 1 6 0Z'};
const icon=(n,cls='')=>`<svg class="${cls}" width="21" height="21" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[n]??icons.file}"/></svg>`;
const roleText=r=>({admin:'Администратор',guard:'Персонал',guest:'Гость'}[r]??r);
const brand=()=>'<div class="brand"><span class="logo">H</span><div><strong>HotelManager</strong><small>Ваш отель в одном месте</small></div></div>';
const btn=(title,action,cls='',extra='')=>`<button class="btn ${cls}" data-act="${action}" ${extra}>${title}</button>`;
const field=(label,name,value='',type='text',extra='')=>`<label class="field"><span>${label}</span><input type="${type}" name="${name}" value="${esc(value)}" ${extra}></label>`;
const select=(label,name,options,value)=>`<label class="field"><span>${label}</span><select name="${name}">${options.map(o=>{const v=Array.isArray(o)?o[0]:o,t=Array.isArray(o)?o[1]:o;return `<option value="${esc(v)}" ${String(value)===String(v)?'selected':''}>${esc(t)}</option>`}).join('')}</select></label>`;
const badge=(s)=>`<span class="badge ${['Заселён','Готов','SUCCESS'].includes(s)?'ok':['Отменён','Ремонт','FAILED','CANCELLED'].includes(s)?'bad':s==='Требуется уборка'?'warn':''}">${esc(s)}</span>`;
const empty=(title,detail,action='')=>`<div class="card empty">${icon('bed')}<h3>${title}</h3><p>${detail}</p>${action}</div>`;
const head=(title,description='',action='')=>`<div class="page-head"><div><h1>${title}</h1><p>${description}</p></div>${action}</div>`;
const app={user:null,state:null,today:new Date().toISOString().slice(0,10),route:'home',trail:[],available:null,filter:{from:'',to:'',people:1,budget:10000,category:'Все'},bookingFilter:'Все',query:'',report:null,dirty:false,modalDirty:false,busy:false,lastSync:null,media:null,scanTimer:null};
let theme;try{theme=localStorage.getItem('hotel-theme')??'light'}catch{theme='light'}document.documentElement.dataset.theme=theme;
function setTheme(){theme=theme==='dark'?'light':'dark';document.documentElement.dataset.theme=theme;try{localStorage.setItem('hotel-theme',theme)}catch{}document.querySelectorAll('button.icon-btn[data-act="theme"]').forEach(b=>b.innerHTML=icon(theme==='dark'?'sun':'moon'))}
function toast(message,bad=false){const div=document.createElement('div');div.className='toast'+(bad?' bad':'');div.textContent=message;$('#toasts').append(div);setTimeout(()=>div.remove(),6500)}
class ApiError extends Error{constructor(status,data){super(data.error??'Не удалось выполнить запрос');this.status=status;this.code=data.code}}
const API_BASE=window.HOTEL_API_BASE??'';
let apiToken='';if(API_BASE)try{apiToken=sessionStorage.getItem('hotel-api-session')??''}catch{}
function rememberToken(value){apiToken=value;if(API_BASE)try{if(value)sessionStorage.setItem('hotel-api-session',value);else sessionStorage.removeItem('hotel-api-session')}catch{}}
async function api(path,method='GET',data){let response;try{response=await fetch(API_BASE+'/api/'+path,{method,headers:{...(method==='POST'?{'Content-Type':'application/json','X-Hotel-Client':'1'}:{}),...(API_BASE&&apiToken?{'Authorization':'Bearer '+apiToken}:{})},body:data===undefined?undefined:JSON.stringify(data),credentials:API_BASE?'omit':'same-origin',cache:'no-store'})}catch{throw new Error('Нет соединения с сервером. Проверьте подключение и повторите попытку.')};const result=await response.json().catch(()=>({error:'Сервер вернул неожиданный ответ'}));if(!response.ok)throw new ApiError(response.status,result);if(API_BASE){if(result.sessionToken)rememberToken(result.sessionToken);if(path==='logout'||(path==='bootstrap'&&!result.user))rememberToken('')}return result}

async function load(quiet=false){const b=await api('bootstrap');app.user=b.user;app.today=b.today??app.today;if(!app.filter.from){app.filter.from=app.today;app.filter.to=plus(app.today,1)}app.state=b.state;app.lastSync=new Date();if(!quiet)renderShellOrAuth();return b}
async function action(p){const payload={...p,requestId:p.requestId??Array.from(crypto.getRandomValues(new Uint8Array(20)),n=>n.toString(16).padStart(2,'0')).join('')};try{return await api('action','POST',payload)}catch(e){if(e.status===428){await pinPrompt();return api('action','POST',payload)}throw e}}
function stopCamera(){clearInterval(app.scanTimer);app.scanTimer=null;if(app.media)app.media.getTracks().forEach(x=>x.stop());app.media=null}
function ask(title,message){return new Promise(resolve=>{const d=$('#confirm');d.innerHTML=`<div class="modal-header"><h2 id="confirm-title">${esc(title)}</h2></div><div class="modal-body">${esc(message)}</div><div class="modal-footer"><button class="btn outline" data-answer="no">Остаться</button><button class="btn" data-answer="yes">Продолжить</button></div>`;const close=v=>{d.close();resolve(v)};d.oncancel=e=>{e.preventDefault();close(false)};$$('button',d).forEach(b=>b.onclick=()=>close(b.dataset.answer==='yes'));d.showModal()})}
async function closeModal(force=false){if(!force&&app.modalDirty&&!await ask('Выйти без сохранения?','Изменения в форме ещё не сохранены. Закрыть её?'))return false;stopCamera();app.modalDirty=false;const d=$('#modal');if(d.open)d.close();return true}
function modal(title,body,footer='',closable=true){stopCamera();app.modalDirty=false;const d=$('#modal');d.innerHTML=`<div class="modal-header"><h2 id="modal-title">${title}</h2>${closable?'<button class="icon-btn" data-act="close-modal" aria-label="Закрыть">'+icon('close')+'</button>':''}</div><div class="modal-body">${body}</div>${footer?'<div class="modal-footer">'+footer+'</div>':''}`;d.oncancel=e=>{e.preventDefault();if(closable)closeModal();else toast('Подтвердите PIN или вернитесь ко входу')};d.oninput=()=>{app.modalDirty=true};if(!d.open)d.showModal();return d}
async function navigate(route,home=false){if(app.dirty&&!await ask('Выйти без сохранения?','Вы изменили данные на странице. Перейти без сохранения?'))return;if(!await closeModal())return;app.dirty=false;if(home)app.trail=[];else if(app.route!==route)app.trail.push(app.route);app.route=route;history.replaceState(null,'','#/'+route);app.query='';renderShell();window.scrollTo({top:0,behavior:'instant'})}
function loginView(register=false){app.dirty=false;$('#app').innerHTML=`<div class="auth-layout"><section class="auth-visual">${brand()}<div><span class="badge">20 номеров · три категории · до 3 гостей</span><h1>Хороший отдых<br>начинается<br>с простых вещей.</h1><p>Найдите свой номер, забронируйте поездку и управляйте проживанием — в одном месте.</p></div><small>Стандарт · Комфорт · Люкс</small></section><section class="auth-panel"><div class="auth-form"><div class="auth-top">${brand()}<button class="icon-btn" data-act="theme" aria-label="Переключить тему">${icon(theme==='dark'?'sun':'moon')}</button></div><h1>${register?'Добро пожаловать':'С возвращением'}</h1><p class="muted">${register?'Создайте гостевой аккаунт для ваших поездок.':'Войдите в личный кабинет гостиницы.'}</p><form id="auth-form" class="stack" data-register="${register}">${register?field('Ваше имя','name','','text','required minlength="2" maxlength="100" autocomplete="name"'):''}${field('Логин','login',register?'':'guest','text','required minlength="3" maxlength="40" autocomplete="username"')}<label class="field"><span>Пароль</span><div class="password"><input name="password" type="password" required ${register?'minlength="8"':''} maxlength="128" autocomplete="${register?'new-password':'current-password'}"><button class="icon-btn" type="button" data-act="password-show" aria-label="Показать пароль">${icon('eye')}</button></div></label>${register?field('Email — необязательно','email','','email','maxlength="120" autocomplete="email"'):''}<div class="error" id="auth-error" role="alert"></div><button class="btn block" type="submit">${register?'Создать аккаунт':'Войти в аккаунт'} ${icon('arrow')}</button><button type="button" class="link" data-act="${register?'login':'register'}">${register?'У меня уже есть аккаунт':'Нет аккаунта? Зарегистрироваться'}</button></form><p class="auth-foot">Общая серверная база · учебная гостиница<br>СБП и QR-платежи работают в демонстрационном режиме.</p></div></section></div>`;
 $('#auth-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,b=$('button[type=submit]',f),p=Object.fromEntries(new FormData(f));b.disabled=true;$('#auth-error').textContent='';try{if(register){await api('register','POST',p);loginView();$('input[name=login]').value=p.login;toast('Аккаунт создан. Войдите с вашим паролем.')}else{await api('login','POST',p);await load()}}catch(err){if($('#auth-error'))$('#auth-error').textContent=err.message}finally{b.disabled=false}};
}
function renderShellOrAuth(){if(!app.user){loginView();return}if(!app.user.verified){loginView();pinFlow();return}renderShell();if(!app.user.onboarded)welcome()}
function pinFlow(){const setup=app.user.needsSetup;modal(setup?'Создайте PIN':'Подтвердите вход',`<form id="pin-form" class="stack"><p class="muted">${setup?'Придумайте PIN из 4–6 цифр. После сохранения запишите одноразовый код восстановления.':'Пароль подтверждён. Введите PIN пользователя '+esc(app.user.login)+'.'}</p>${field(setup?'Новый PIN':'PIN','pin','','password','required inputmode="numeric" pattern="[0-9]{4,6}" minlength="4" maxlength="6" autocomplete="off"')}<div class="error" id="pin-error"></div><button class="btn block" type="submit">${setup?'Сохранить PIN':'Открыть приложение'}</button>${!setup?'<button class="link" type="button" data-act="recover">Не помню PIN</button>':''}<button class="link" type="button" data-act="logout">Домой · ко входу</button></form>`,'',false);$('#pin-form').onsubmit=async e=>{e.preventDefault();const b=$('button[type=submit]',e.currentTarget);b.disabled=true;try{const r=await api(setup?'pin/setup':'pin','POST',Object.fromEntries(new FormData(e.currentTarget)));app.modalDirty=false;if(r.recovery)showRecovery(r.recovery);else{await closeModal(true);await load()}}catch(err){$('#pin-error').textContent=err.message}finally{b.disabled=false}}}
function showRecovery(code){modal('Сохраните код восстановления',`<div class="stack"><p>Этот код показывается один раз. Храните его отдельно от телефона. Для сброса PIN также нужен пароль.</p><div class="code">${esc(code)}</div>${btn('Я записал код — продолжить','recovery-done','block')}</div>`,'',false)}
function recoveryFlow(){modal('Восстановление PIN',`<form id="recover-form" class="stack"><p class="muted">Пароль уже подтверждён. Введите сохранённый код и придумайте новый PIN.</p>${field('Одноразовый код','code','','text','required maxlength="100" autocomplete="off"')}${field('Новый PIN','pin','','password','required inputmode="numeric" pattern="[0-9]{4,6}" maxlength="6"')}<div class="error" id="recover-error"></div><button class="btn" type="submit">Восстановить доступ</button><button class="link" type="button" data-act="logout">Ко входу</button></form>`,'',false);$('#recover-form').onsubmit=async e=>{e.preventDefault();try{const r=await api('pin/recover','POST',Object.fromEntries(new FormData(e.currentTarget)));showRecovery(r.recovery)}catch(err){$('#recover-error').textContent=err.message}}}
function pinPrompt(){return new Promise((resolve,reject)=>{modal('Подтверждение администратора',`<form id="stepup-form" class="stack"><p class="muted">Перед важным действием подтвердите свой PIN.</p>${field('PIN','pin','','password','required inputmode="numeric" pattern="[0-9]{4,6}" maxlength="6"')}<div class="error" id="stepup-error"></div><button class="btn" type="submit">Подтвердить</button><button class="btn outline" type="button" id="stepup-cancel">Отмена</button></form>`,'',false);$('#stepup-cancel').onclick=()=>{closeModal(true);reject(new Error('Действие отменено'))};$('#stepup-form').onsubmit=async e=>{e.preventDefault();try{await api('pin','POST',Object.fromEntries(new FormData(e.currentTarget)));await closeModal(true);resolve()}catch(err){$('#stepup-error').textContent=err.message}}})}
function welcome(){const staff=app.user.role!=='guest';modal('Добро пожаловать в HotelManager',`<div class="stack"><div class="hero"><div><span class="label">ВАШ ОТЕЛЬ В БРАУЗЕРЕ</span><h2>Все важные дела —<br>в одном месте.</h2><p>Начните с короткого знакомства.</p></div></div><p>${staff?'Здесь находятся бронирования, заселение, гости и обслуживание номеров. Функции зависят от вашей роли.':'Выберите даты и номер. Отель, ночи, стоимость и ваши контакты подставятся автоматически.'}</p><div class="info">${staff?'Камера нужна для учебной проверки QR-пропусков. Браузер спросит разрешение только после вашего нажатия. Без камеры остальные разделы доступны.':'Для бронирования не требуется разрешать камеру или доступ ко всем файлам.'}</div>${btn('Открыть руководство','welcome-guide','outline block')}${staff?btn('Продолжить и запросить камеру','welcome-camera','block'):btn('Перейти на главную','welcome-done','block')}${staff?btn('Продолжить без камеры','welcome-done','outline block'):''}</div>`,'',false)}
async function finishWelcome(camera=false){if(camera){try{if(!navigator.mediaDevices?.getUserMedia)throw new Error('Камера доступна только через HTTPS или localhost. Можно продолжить без неё.');const media=await navigator.mediaDevices.getUserMedia({video:true,audio:false});media.getTracks().forEach(t=>t.stop());toast('Доступ к камере разрешён')}catch(e){toast(e.name==='NotAllowedError'?'Камера не разрешена. Вы можете включить её позже в сканере.':e.message,true)}}await action({kind:'onboard.done'});await closeModal(true);await load()}
const NAV_GUEST=[['home','search','Поиск номера'],['bookings','calendar','Мои бронирования'],['notifications','bell','Уведомления'],['profile','people','Мой профиль']];
function navItems(){if(app.user.role==='guest')return NAV_GUEST;return [['home','home','Обзор'],['calendar','calendar','Календарь'],['bookings','bed','Бронирования'],['rooms','search','Номера'],['guests','people','Гости'],['housekeeping','check','Уборка'],...(app.user.role==='admin'?[['reports','chart','Отчёты'],['notifications','bell','Уведомления'],['audit','shield','Журнал']]:[]),['labs','file','Лабораторные'],['settings','settings','Настройки'],['help','help','Помощь']]}
const titles={home:'Обзор',rooms:'Подбор номера',bookings:'Бронирования',notifications:'Уведомления',profile:'Мой профиль',calendar:'Календарь',guests:'Карточки гостей',housekeeping:'Уборка и обслуживание',reports:'Отчёты',audit:'Журнал действий',labs:'Лабораторные работы',settings:'Настройки',help:'Помощь',tasks:'Задачи смены',notes:'Заметки',security:'Безопасность',scanner:'QR-пропуска',sync:'Общая база и обмен'};
function unread(){return app.state?.notices?.filter(n=>!n.readBy.includes(app.user.id)).length??0}
function renderShell(){if(!app.user?.verified||!app.state)return;const current=app.route.split('/')[0],nav=navItems(),guest=app.user.role==='guest';const allowed=new Set([...nav.map(x=>x[0]),'stay','profile','help',...(guest?[]:['tasks','notes','security','scanner','sync'])]);if(!allowed.has(current)){app.route='home';return renderShell()}
 $('#app').innerHTML=`<div class="app-shell"><aside class="sidebar" id="sidebar">${brand()}<div class="label">${guest?'ЛИЧНЫЙ КАБИНЕТ':'РАБОЧЕЕ ПРОСТРАНСТВО'}</div><nav>${nav.map(([route,ico,title])=>`<button class="nav-item ${current===route?'active':''}" data-nav="${route}">${icon(ico)}<span>${title}</span>${route==='notifications'&&unread()?'<span class="count">'+unread()+'</span>':''}</button>`).join('')}<button class="nav-item ${current==='help'?'active':''}" data-nav="help" ${guest?'':'hidden'}>${icon('help')}Помощь</button></nav><div class="account"><div class="row"><span class="avatar">${esc(app.user.name.slice(0,1).toUpperCase())}</span><div class="grow"><strong>${esc(app.user.name)}</strong><small>${roleText(app.user.role)}</small></div></div><button class="nav-item" data-act="logout">${icon('logout')}Выйти из аккаунта</button></div></aside><div class="mobile-scrim" data-act="menu-close"></div><div class="workspace"><header class="topbar"><div class="row gap8"><button class="icon-btn mobile-menu" data-act="menu" aria-label="Открыть меню">${icon('menu')}</button><div><div class="eyebrow">${esc(app.state.hotel.name)}</div><h2>${current==='stay'?'Бронь и проживание':guest&&current==='home'?'Ваше следующее путешествие':titles[current]??'HotelManager'}</h2></div></div><div class="top-actions"><span class="online">Общая база подключена</span><button class="icon-btn" data-act="theme" aria-label="Переключить тему">${icon(theme==='dark'?'sun':'moon')}</button><button class="icon-btn" data-nav="help" aria-label="Руководство">${icon('help')}</button><button class="btn secondary sm" data-act="home" aria-label="На главную">${icon('home')}<span class="home-label">Домой</span></button>${app.user.role==='admin'?'<button class="icon-btn notification-btn" data-nav="notifications" aria-label="Уведомления">'+icon('bell')+(unread()?'<span class="dot-count">'+unread()+'</span>':'')+'</button>':''}<span class="avatar" title="${esc(app.user.name)}">${esc(app.user.name.slice(0,1).toUpperCase())}</span></div></header><main class="page" id="page" tabindex="-1"></main></div>${guest?`<nav class="bottom-nav" aria-label="Основные разделы">${NAV_GUEST.map(([r,i,t])=>`<button data-nav="${r}" class="${current===r?'active':''}">${icon(i)}<span>${r==='home'?'Поиск':r==='bookings'?'Брони':r==='profile'?'Профиль':t}</span></button>`).join('')}</nav>`:''}</div>`;
 renderPage();
}
function cardRoom(r){return `<article class="room-card"><div class="room-image"><img src="./assets/${r.image}.jpg" alt="Интерьер категории ${esc(r.category)}" loading="lazy"><span class="badge">№${r.id}</span></div><div class="room-content"><div class="row between"><h3>${esc(r.category)}</h3><span class="badge ok">Подходит</span></div><p>До ${r.capacity} гостей · Wi-Fi · завтрак</p><div class="row between"><div><div class="price">${money(r.price)}</div><small>за номер / ночь</small></div>${btn('Выбрать','room-book','','data-id="'+r.id+'"')}</div></div></article>`}
function searchForm(){const f=app.filter;return `<form id="search-form"><div class="search-row">${field('Заезд','from',f.from,'date',`required min="${app.today}"`)}${field('Выезд','to',f.to,'date',`required min="${plus(f.from,1)}"`)}${select('Гости','people',[[1,'1 гость'],[2,'2 гостя'],[3,'3 гостя']],f.people)}<button class="btn" type="submit">${icon('search')}Найти номер</button></div><div class="filter-line no-print"><div class="chips">${['Все','Стандарт','Комфорт','Люкс'].map(c=>`<button class="chip ${c===f.category?'active':''}" data-category="${c}" type="button">${c}</button>`).join('')}</div><label class="field"><span>Бюджет за ночь, ₽</span><input name="budget" type="number" min="1" max="10000000" value="${f.budget}" required></label></div></form>`}
async function fillAvailability(){const target=$('#room-results');if(!target)return;target.innerHTML='<div class="card muted">Проверяем доступность номеров…</div>';try{const params=new URLSearchParams(app.filter);const r=await api('availability?'+params);app.available=r.rooms;const el=$('#room-results');if(!el)return;el.innerHTML=`<div class="section-heading"><h2>Подходит номеров: ${r.rooms.length}</h2><small>${date(app.filter.from)} — ${date(app.filter.to)} · гостей: ${app.filter.people}</small></div>${r.rooms.length?'<div class="room-grid">'+r.rooms.map(cardRoom).join('')+'</div>':empty('На эти даты свободных номеров нет','Попробуйте изменить период, категорию или бюджет.')}` }catch(e){if($('#room-results'))$('#room-results').innerHTML=`<div class="error">${esc(e.message)}</div>`}}
function guestHome(){const b=app.state.bookings.filter(b=>['Забронирован','Заселён'].includes(b.status)).sort((a,b)=>a.arrival.localeCompare(b.arrival))[0];return `${head('Ваше следующее путешествие','Комфорт начинается с подходящего номера.')}<section class="hero room-hero"><div><span class="label">ВАШЕ МЕСТО ДЛЯ ОТДЫХА</span><h1>Чувствуйте себя<br>как дома.</h1><p>Стандарт, комфорт или люкс — выбирайте свой ритм. Все категории доступны для 1–3 гостей.</p></div></section><div class="card search-card">${searchForm()}</div>${b?'<div class="section-heading"><h2>Ближайшая поездка</h2></div>'+bookingCard(b):''}<div id="room-results"></div><p class="muted auth-foot">Фотографии показывают пример интерьера категории. Заезд с 14:00, выезд до 12:00.</p>`}
function metric(label,value,ico){return `<div class="metric"><span class="symbol">${icon(ico)}</span><div><small>${label}</small><strong>${value}</strong></div></div>`}
function dashboard(){const s=app.state,active=s.bookings.filter(b=>b.status==='Заселён'),arrivals=s.bookings.filter(b=>b.arrival===app.today&&b.status==='Забронирован'),departures=s.bookings.filter(b=>b.departure<=app.today&&b.status==='Заселён'),busy=new Set(active.map(b=>b.roomId)),careRooms=new Set(s.care.filter(c=>c.status!=='Готов').map(c=>c.roomId));return `${head('Ваш отель сегодня','Заезды, проживание и всё, что требует внимания.',btn(icon('plus')+' Новая бронь','new-booking'))}<div class="metrics">${metric('Всего номеров',20,'bed')}${metric('Проживают',busy.size,'people')}${metric('Ожидают заезда',arrivals.length,'calendar')}${metric('Нужно подготовить',careRooms.size,'check')}</div><div class="section-heading"><h2>Быстрые действия</h2><small>Серверная дата: ${date(app.today)}</small></div><div class="grid cols3"><button class="card lab-card" data-nav="rooms">${icon('search')}<h3>Подобрать номер</h3><p>Найдите свободную категорию на нужные даты.</p></button><button class="card lab-card" data-nav="bookings">${icon('people')}<h3>Заселение и выезд</h3><p>Проверьте бронь, документы и счёт гостя.</p></button><button class="card lab-card" data-nav="housekeeping">${icon('check')}<h3>Подготовка номеров</h3><p>Уборка, ремонт и готовность к заезду.</p></button></div><div class="section-heading"><h2>Ближайшие задачи</h2>${btn('Все бронирования','to-bookings','outline sm')}</div>${arrivals.length||departures.length?'<div class="booking-list">'+[...arrivals,...departures].map(bookingCard).join('')+'</div>':empty('Сегодня всё спокойно','Здесь появятся ожидаемые заезды и выезды.',btn('Создать бронирование','new-booking','secondary'))}<div class="section-heading"><h2>Недавние бронирования</h2></div>${s.bookings.length?bookingTable(s.bookings.slice(-6).reverse()):empty('Гостиница готова к первым гостям','Создайте бронь или войдите в гостевой аккаунт для демонстрации.')}`}
function invoice(b){const s=app.state,lodging=b.status==='Отменён'?0:b.total,services=s.charges.filter(c=>c.bookingId===b.id).reduce((n,c)=>n+c.price*c.quantity,0),paid=s.payments.filter(p=>p.bookingId===b.id).reduce((n,p)=>n+p.amount,0);return{lodging,services,total:lodging+services,paid,balance:lodging+services-paid}}
function roomBy(id){return app.state.rooms.find(r=>r.id===Number(id))}
function bookingCard(b){const r=roomBy(b.roomId),bill=invoice(b);return `<article class="card booking-card"><img src="./assets/${r.image}.jpg" alt="${esc(r.category)}"><div class="grow"><h3>№${b.roomId} · ${esc(r.category)}</h3><p>${esc(b.guest)}</p><small>${date(b.arrival)} — ${date(b.departure)} · ${b.people} гост.</small>${badge(b.status)}</div><div class="end"><div><strong>${money(bill.total)}</strong><small>Остаток: ${money(bill.balance)}</small></div>${btn('Открыть бронь','stay','sm','data-id="'+esc(b.id)+'"')}</div></article>`}
function bookingTable(rows){return `<div class="table-scroll"><table><thead><tr><th>Гость / номер</th><th>Даты проживания</th><th>Гости</th><th>Счёт / остаток</th><th>Статус</th><th></th></tr></thead><tbody>${rows.map(b=>{const r=roomBy(b.roomId),i=invoice(b);return `<tr><td><strong>${esc(b.guest)}</strong><small>№${b.roomId} · ${r.category}</small></td><td>${date(b.arrival)} — ${date(b.departure)}</td><td>${b.people}</td><td>${money(i.total)}<small>Остаток: ${money(i.balance)}</small></td><td>${badge(b.status)}</td><td>${btn('Открыть','stay','secondary sm','data-id="'+b.id+'"')}</td></tr>`}).join('')}</tbody></table></div>`}
function bookingsPage(){return `${head(app.user.role==='guest'?'Ваши поездки':'Управление проживанием','Бронирования, заселение и счета гостей.',btn(icon('plus')+' Новая бронь','new-booking'))}<div class="filter-line"><div class="chips">${['Все','Забронирован','Заселён','Выселен','Отменён'].map(t=>`<button class="chip ${t===app.bookingFilter?'active':''}" data-status-filter="${t}">${t}</button>`).join('')}</div><input id="booking-search" placeholder="Имя гостя или номер" value="${esc(app.query)}" aria-label="Поиск бронирования"></div><div id="booking-rows"></div>`}
function fillBookings(){const rows=app.state.bookings.filter(b=>(app.bookingFilter==='Все'||b.status===app.bookingFilter)&&`${b.guest} ${b.roomId}`.toLowerCase().includes(app.query.toLowerCase())).sort((a,b)=>b.created.localeCompare(a.created));$('#booking-rows').innerHTML=rows.length?((app.user.role==='guest'||narrow.matches)?'<div class="booking-list">'+rows.map(bookingCard).join('')+'</div>':bookingTable(rows)):empty('Бронирований с такими условиями нет','Выберите другие фильтры или найдите номер для новой поездки.',btn('Найти номер','new-booking','secondary'))}
function stayPage(id){const b=app.state.bookings.find(b=>b.id===id);if(!b)return empty('Бронь недоступна','Запись не найдена или принадлежит другому гостю.');const r=roomBy(b.roomId),i=invoice(b),staff=app.user.role!=='guest';return `${head('Ваше проживание','Бронь '+b.id.slice(0,8),btn(icon('refresh')+' Обновить','refresh','outline sm'))}<div class="split"><div class="stack"><article class="room-card"><img class="full" style="max-height:270px;object-fit:cover" src="./assets/${r.image}.jpg" alt="${esc(r.category)}"><div class="room-content"><div class="row between"><h2>№${r.id} · ${r.category}</h2>${badge(b.status)}</div><h3>${esc(b.guest)}</h3><p>${esc(app.state.hotel.name)} · ${esc(app.state.hotel.address)}</p><div class="grid cols3"><div><small>Заезд</small><strong>${date(b.arrival)}</strong></div><div><small>Выезд</small><strong>${date(b.departure)}</strong></div><div><small>Гости / ночи</small><strong>${b.people} / ${(Date.parse(b.departure)-Date.parse(b.arrival))/86400000}</strong></div></div><div class="info">${esc(b.phone||'Телефон не указан')}<br>${esc(b.email||'Email не указан')}<br>${esc(b.wishes||'Без дополнительных пожеланий')}</div><div class="row wrap">${['Забронирован','Заселён'].includes(b.status)&&(staff||b.status==='Забронирован')?btn('Изменить даты / номер','amend','outline sm',`data-id="${b.id}"`):''}${b.status==='Забронирован'&&staff?btn('Заселить гостя','status','sm',`data-id="${b.id}" data-target="Заселён"`):''}${b.status==='Заселён'&&staff?btn('Оформить выезд','status','sm',`data-id="${b.id}" data-target="Выселен"`):''}${b.status==='Забронирован'?btn('Отменить бронь','status','danger sm',`data-id="${b.id}" data-target="Отменён"`):''}${btn('Повторить поездку','repeat','secondary sm',`data-id="${b.id}"`)}${staff?btn('Контакты гостя','booking-contact','outline sm',`data-id="${b.id}"`):''}</div></div></article><div class="card"><h3>Услуги и оплаты</h3>${app.state.charges.filter(c=>c.bookingId===id).map(c=>`<div class="money-line"><div>${esc(c.title)}<small> · ${c.quantity} × ${money(c.price)}</small></div><span>${money(c.quantity*c.price)} ${staff?'<button class="link" data-act="service-remove" data-id="'+c.id+'" aria-label="Удалить услугу">×</button>':''}</span></div>`).join('')}${app.state.payments.filter(p=>p.bookingId===id).map(p=>`<div class="money-line"><div>${esc(p.method)}<small> · ${stamp(p.at)}</small></div><strong>${money(p.amount)}</strong></div>`).join('')}${!app.state.charges.some(c=>c.bookingId===id)&&!app.state.payments.some(p=>p.bookingId===id)?'<p class="muted">Дополнительных начислений и оплат пока нет.</p>':''}</div></div><aside class="stack"><div class="card"><h2>Счёт проживания</h2><div class="money-line"><span>Номер</span><strong>${money(i.lodging)}</strong></div><div class="money-line"><span>Услуги</span><strong>${money(i.services)}</strong></div><div class="money-line"><span>Принято</span><strong>${money(i.paid)}</strong></div><div class="money-line total"><span>${i.balance<0?'К возврату':'К оплате'}</span><span>${money(Math.abs(i.balance))}</span></div><div class="stack">${i.balance>0&&b.status!=='Отменён'?btn('Оплатить СБП / QR','demo-pay','block',`data-id="${id}"`):''}${staff&&['Забронирован','Заселён'].includes(b.status)?btn('Добавить услугу','service','outline block',`data-id="${id}"`):''}${staff&&i.balance>0?btn('Учесть оплату','manual-pay','outline block',`data-id="${id}"`):''}${staff&&i.paid>0?btn('Учесть возврат','refund','danger block',`data-id="${id}"`):''}</div><p class="auth-foot">СБП / QR — симуляция, без списания реальных денег.</p></div><div class="card"><h3>Всё для вашего отдыха</h3><p class="muted">Заезд с 14:00 · выезд до 12:00.<br>Есть вопрос? Обратитесь к администратору гостиницы.</p></div></aside></div>`}
function notificationsPage(){if(app.user.role==='admin'){const rows=app.state.notices.slice().reverse();return `${head('Действия гостей','Брони, контакты и учебные платежи из общей базы.',btn('Отметить всё прочитанным','notice-read','outline sm'))}<div class="stack">${rows.length?rows.map(n=>`<article class="card"><div class="row between"><h3>${!n.readBy.includes(app.user.id)?'<span class="badge">Новое</span> ':''}${esc(n.title)}</h3><small>${stamp(n.at)}</small></div><p class="muted pre">${esc(n.detail)}</p><div class="row between"><small>${esc(n.actor)}</small>${n.bookingId?btn('Открыть бронь','stay','secondary sm',`data-id="${n.bookingId}"`):''}</div></article>`).join(''):empty('Пока нет новых действий','После сохранения гостем брони, контактов или учебной оплаты событие появится здесь.')}</div>`}const rows=app.state.bookings.filter(b=>['Забронирован','Заселён'].includes(b.status));return `${head('Ваши уведомления','Ближайшие поездки и напоминания о проживании.')}<div class="booking-list">${rows.length?rows.map(bookingCard).join(''):empty('Новых напоминаний нет','Здесь будут показаны ваши активные поездки.')}</div>`}
function profileForm(u,formId='profile-form'){return `<form id="${formId}" class="stack"><div class="form-grid">${field('Имя гостя','name',u.name,'text','required minlength="2" maxlength="100" autocomplete="name"')}${field('Телефон','phone',u.phone,'tel','maxlength="30" autocomplete="tel"')}${field('Email','email',u.email,'email','maxlength="120" autocomplete="email"')}<label class="field span2"><span>Пожелания</span><textarea name="wishes" maxlength="1000">${esc(u.wishes)}</textarea></label></div><div class="error form-error"></div><button class="btn" type="submit">Сохранить данные</button></form>`}
function profilePage(){const u=app.user;return `${head('Ваш личный кабинет','Контакты подставляются в новые бронирования.')}<div class="split"><div class="card"><h2>Личные данные</h2>${profileForm(u)}</div><aside class="stack"><div class="card"><div class="row"><span class="avatar">${esc(u.name.slice(0,1))}</span><div><h3>${esc(u.name)}</h3><small>${esc(u.login)} · ${roleText(u.role)}</small></div></div><hr class="divider"><p class="muted">Ваши записи хранятся на сервере и доступны после входа на другом устройстве.</p></div><div class="card"><h3>Оформление</h3><p class="muted">Светлая и тёмная темы работают на всех страницах.</p>${btn('Переключить тему','theme','outline block')}</div><div class="card"><h3>Учебный пропуск</h3><p class="muted">Демонстрация QR для лабораторной работы, не реальный пропуск.</p>${btn('Показать QR-пример','pass-qr','outline block')}</div>${btn('Выйти из аккаунта','logout','danger block')}</aside></div>`}
function housekeepingPage(){return `${head('Комнаты, готовые к новому отдыху','Состояние уборки и ремонта влияет на подбор номеров.')}<div class="room-grid">${app.state.rooms.map(r=>{const c=app.state.care.find(c=>c.roomId===r.id)??{status:'Готов',note:''};const occupied=app.state.bookings.some(b=>b.roomId===r.id&&b.status==='Заселён');return `<article class="card stack"><div class="row between"><h3>№${r.id} · ${r.category}</h3>${badge(occupied?'Заселён':c.status)}</div><p class="muted">${esc(c.note||'Примечаний нет')}</p>${btn('Изменить состояние','care','outline block',`data-id="${r.id}"`)}</article>`}).join('')}</div>`}
function guestsPage(){const profiles=app.state.users.filter(u=>u.role==='guest');const walkins=app.state.bookings.filter(b=>!profiles.some(u=>u.id===b.owner));return `${head('Гости гостиницы','Контакты аккаунтов и сведения в бронированиях.')}<div class="grid cols3">${profiles.map(u=>`<article class="card stack"><div class="row"><span class="avatar">${esc(u.name.slice(0,1))}</span><h3>${esc(u.name)}</h3></div><p class="muted">${esc(u.phone||'Телефон не указан')}<br>${esc(u.email||'Email не указан')}</p><small>Бронирований: ${app.state.bookings.filter(b=>b.owner===u.id).length}</small>${btn('Изменить контакты','guest-edit','outline block',`data-id="${u.id}"`)}</article>`).join('')}</div>${walkins.length?'<div class="section-heading"><h2>Гости без личного аккаунта</h2></div><div class="booking-list">'+walkins.map(bookingCard).join('')+'</div>':''}`}
function calendarPage(){const start=app.calendarStart??app.today,days=Array.from({length:7},(_,i)=>plus(start,i));return `${head('Календарь проживания','Семь дней загрузки. Нажмите на бронь, чтобы открыть её.',`<div class="row">${btn('← Неделя','calendar-prev','outline sm')}${btn('Неделя →','calendar-next','outline sm')}</div>`)}<div class="table-scroll card"><div class="calendar"><div><strong>Номер</strong></div>${days.map(d=>`<div><strong>${date(d)}</strong></div>`).join('')}${app.state.rooms.map(r=>`<div><strong>№${r.id}</strong><br>${r.category}</div>`+days.map(d=>{const b=app.state.bookings.find(b=>b.roomId===r.id&&!['Отменён','Выселен'].includes(b.status)&&b.arrival<=d&&b.departure>d);const repair=r.care==='Ремонт';return `<div class="${b?(b.status==='Заселён'?'checked':'occupied'):repair?'repair':''}">${b?`<button class="link" data-act="stay" data-id="${b.id}">${esc(b.guest)}</button>`:repair?'Ремонт':'Свободен'}</div>`}).join('')).join('')}</div></div>`}
function reportsPage(){const r=app.report;return `${head('Понятные цифры вашего отеля','Период задаётся включительно, по датам гостиницы.',`<div class="row wrap">${btn(icon('file')+' CSV','report-csv','outline sm')}${btn('PDF / печать','print','secondary sm')}</div>`)}<form id="report-form" class="card form-grid no-print">${field('С даты','from',r?.from??app.today,'date','required')}${field('По дату','to',r?.to??plus(app.today,30),'date','required')}<button class="btn" type="submit">Сформировать отчёт</button></form><div id="report-results">${r?`<div class="section-heading"><h2>${date(r.from)} — ${date(r.to)}</h2></div><div class="metrics">${metric('Бронирований',r.count,'calendar')}${metric('Отменено',r.cancelled,'file')}${metric('Начислено',money(r.booked),'chart')}${metric('Принято, нетто',money(r.received),'card')}</div><div class="section-heading"><h2>Категории</h2></div><div class="grid cols3">${r.categories.map(c=>`<div class="card"><small>${esc(c.name)}</small><h2>${c.count} броней</h2></div>`).join('')}</div><div class="section-heading"><h2>Записи за период</h2></div>${r.rows.length?bookingTable(r.rows):empty('За период записей нет','Выберите другой диапазон дат.')}`:'<div class="empty muted">Выберите период и сформируйте отчёт.</div>'}</div>`}
function auditPage(){const rows=app.state.audit.slice().reverse().filter(e=>`${e.actor} ${e.action} ${e.detail}`.toLowerCase().includes(app.query.toLowerCase()));return `${head('Журнал действий','События сервера: входы, изменения и отказы в доступе.',btn('Экспорт JSON','export','outline sm'))}<div class="filter-line"><input id="audit-search" value="${esc(app.query)}" placeholder="Пользователь или действие" aria-label="Поиск по журналу"><small>Показаны последние ${Math.min(rows.length,250)} из ${rows.length} событий</small></div><div class="table-scroll"><table><thead><tr><th>Время</th><th>Пользователь</th><th>Действие</th><th>Результат</th><th>Подробности</th></tr></thead><tbody>${rows.slice(0,250).map(e=>`<tr><td>${stamp(e.at)}</td><td>${esc(e.actor)}</td><td>${esc(e.action)}</td><td>${badge(e.allowed?'Разрешено':'Отказ')}</td><td>${esc(e.detail)}</td></tr>`).join('')}</tbody></table></div>`}
function settingsPage(){return `${head('Приложение под ваш отель','Настройки оформления и сведения гостиницы.')}<div class="grid cols2">${app.user.role==='admin'?`<div class="card"><h2>Данные гостиницы</h2><form id="hotel-form" class="stack">${field('Название отеля','name',app.state.hotel.name,'text','required minlength="2" maxlength="100"')}${field('Адрес','address',app.state.hotel.address,'text','required minlength="3" maxlength="200"')}<div class="error form-error"></div><button class="btn" type="submit">Сохранить данные отеля</button></form></div>`:''}<div class="card stack"><h2>Оформление и сессия</h2><p class="muted">Тема сохраняется на этом устройстве. Бизнес-данные хранятся в общей базе сервера.</p>${btn('Светлая / тёмная тема','theme','outline block')}${btn('Личные данные','profile-link','outline block')}${btn('Моё руководство','help-link','outline block')}${btn('Выйти из аккаунта','logout','danger block')}</div></div>`}
const LABS=[['6','Навигация','Главная, каталог и сведения о брони.','rooms'],['7','Загрузка данных','Запрос доступности с сервера и обработка ошибок.','rooms'],['8','Профиль и оформление','Адаптивные страницы, светлая и тёмная темы.','profile'],['9','Задачи смены','Добавление, отметка выполнения и удаление.','tasks'],['10','HTTP API','Данные гостиницы загружаются по API сервера.','sync'],['11','Заметки и JSON','Серверное сохранение, импорт и экспорт заметок.','notes'],['12','Модель угроз','Пароли, сессии, данные гостей и границы доступа.','security'],['13','Подтверждение доступа','PIN, код восстановления и серверная сессия.','security'],['14','Роли и QR','Камера по разрешению и учебная проверка пропуска.','scanner'],['15','Общая база','Обновление данных между разными браузерами.','sync'],['16','Аудит и проверка','Журнал сервера и результаты контрольных сценариев.','security']];
function labsPage(){return `${head('Лабораторные в браузере','Веб-адаптация функций приложения. Android API заменены браузерными и серверными механизмами.')}<div class="lab-grid">${LABS.map(([id,title,desc,path])=>`<article class="card lab-card"><span class="lab-number">ЛАБОРАТОРНАЯ ${id}</span><h3>${title}</h3><p>${desc}</p><button class="btn outline sm" data-nav="${path}">Открыть раздел</button></article>`).join('')}</div><p class="auth-foot">Android Keystore и системная биометрия не имитируются. Здесь используются серверные хеши, HttpOnly-сессии и PIN; синхронизация выполняется запросами каждые 15 секунд, а не WebSocket.</p>`}
function tasksPage(){return `${head('Задачи вашей смены','Список сохраняется на сервере для вашей учётной записи.')}<form id="task-form" class="card row no-print">${field('Новая задача','title','','text','required maxlength="200"')}<button class="btn" type="submit">${icon('plus')}Добавить</button></form><div class="stack section-heading">${app.state.tasks.length?app.state.tasks.map(t=>`<div class="card row full"><button class="icon-btn" data-act="task-toggle" data-id="${t.id}" aria-label="Изменить выполнение">${icon(t.done?'check':'calendar')}</button><span class="grow ${t.done?'muted':''}">${esc(t.title)}</span><button class="icon-btn" data-act="task-delete" data-id="${t.id}" aria-label="Удалить задачу">${icon('close')}</button></div>`).join(''):empty('Задач пока нет','Добавьте первый пункт для своей смены.')}</div>`}
function notesPage(){return `${head('Заметки смены','Личные записи сохраняются в общей базе под вашим аккаунтом.',`<div class="row wrap">${btn('Импорт JSON','notes-import','outline sm')}${btn('Экспорт','notes-export','outline sm')}${btn(icon('plus')+' Новая','note-new','sm')}</div>`)}<input type="file" id="notes-file" accept="application/json,.json" hidden><div class="grid cols3">${app.state.notes.map(n=>`<article class="card stack"><small>${stamp(n.at)}</small><h3>${esc(n.title)}</h3><p class="muted pre">${esc(n.body.slice(0,200))}${n.body.length>200?'…':''}</p><div class="row">${btn('Открыть','note-edit','outline sm',`data-id="${n.id}"`)}${btn('Удалить','note-delete','danger sm',`data-id="${n.id}"`)}</div></article>`).join('')}</div>${!app.state.notes.length?empty('Место для важных деталей','Добавьте заметку, чтобы не потерять договорённости.'):''}`}
function securityPage(){return `${head('Проверка безопасности','Механизмы веб-версии и их практические границы.')}<div class="grid cols2"><div class="card stack"><h2>Ваша сессия</h2><p>${esc(app.user.login)} · ${roleText(app.user.role)}</p><div class="info">Cookie сессии — HttpOnly и SameSite=Strict. Пароли и PIN хешируются с солью на сервере. Доступ к чужим данным проверяется в API.</div>${btn('Подтвердить свой PIN','pin-check','outline block')}<p class="muted">Пароль, PIN и код восстановления не отправляются в журнал действий и не экспортируются в отчётах.</p></div><div class="card stack"><h2>Контрольные сценарии</h2><p>1. Гость не меняет чужую бронь.<br>2. Две заявки не занимают один номер на пересекающиеся даты.<br>3. Повторный платёж не дублируется.<br>4. Запрос с другого Origin отклоняется.<br>5. Гость не меняет настройки отеля.</p><p class="muted">Автоматические проверки находятся в tests/. Этот экран не выдаёт ручной сценарий за выполненный тест.</p></div></div><div class="card guide section-heading"><div><h2>Модель угроз</h2><p>Защищаем контакты гостей, бронирования и учебный финансовый журнал от доступа чужих аккаунтов, повторных запросов и конфликтов записи. Сервер считает сумму сам и не доверяет роли, цене или владельцу, присланным из браузера.</p><p>Учебные аккаунты имеют опубликованные пароли. Для реальных данных нужны собственные реквизиты, HTTPS, резервирование и эксплуатационная настройка сервера. QR-пропуск и оплата являются демонстрационными функциями.</p></div></div>`}
function syncPage(){return `${head('Одна гостиница — общие данные','Изменения доступны после входа с другого устройства.')}<div class="grid cols2"><div class="card stack"><h2>Подключение активно</h2><div class="online">Серверная база подключена</div><p>Последнее обновление: ${app.lastSync?.toLocaleTimeString('ru-RU')??'—'}</p><p>Ревизия данных: ${app.state.revision}</p>${btn(icon('refresh')+' Обновить сейчас','refresh','block')}<small>Автоматическая проверка — каждые 15 секунд. Открытая форма не перезаписывается фоновым обновлением.</small></div><div class="card stack"><h2>Как показать преподавателю</h2><p>В одном браузере войдите как guest, в другом — как admin. Создайте бронь гостем, затем обновите панель администратора. Откройте уведомление и проверьте запись.</p><p class="muted">На локальном сервере оба компьютера должны использовать адрес одного запущенного сервера. Отдельные копии сервера имеют отдельные базы.</p></div></div>`}
function scannerPage(){return `${head('Учебная проверка пропуска','Доступно только персоналу. Камера включается после вашего согласия.')}<div class="grid cols2"><div class="card stack"><h2>Сканирование камерой</h2><video id="scan-video" class="video-box" playsinline muted hidden></video>${btn(icon('camera')+' Включить камеру','camera-start','block')}${btn('Остановить камеру','camera-stop','outline block')}<p class="muted">Для камеры требуется HTTPS или localhost. Если BarcodeDetector не поддерживается браузером, используйте ручной ввод.</p></div><div class="card"><h2>Ручная проверка</h2><form id="pass-form" class="stack">${field('Учебный код','code','HOTEL:guest','text','required maxlength="200"')}<div class="error form-error"></div><button class="btn" type="submit">Проверить на сервере</button></form><div class="info">Демонстрационные коды: HOTEL:guest, HOTEL:guard, HOTEL:admin. Это не механизм реального допуска людей в гостиницу.</div></div></div>`}
function guideHtml(admin){return `<article class="guide"><span class="label">HOTELMANAGER WEB · РУКОВОДСТВО</span><h1>${admin?'Руководство администратора':'Руководство гостя'}</h1><h2>1. Вход и первый запуск</h2><p>Войдите по логину и паролю. В первый раз создайте PIN из 4–6 цифр и запишите одноразовый код восстановления. В следующих сеансах введите свой PIN после пароля. Учётные данные сотрудников выдаёт администратор. Для личного гостевого аккаунта используйте регистрацию.</p><p>${admin?'Персоналу предлагается доступ к камере для учебных QR-пропусков. Можно продолжить без камеры; браузерный запрос выполняется только по нажатию кнопки. Камера работает на HTTPS или localhost.':'Для бронирования камера и разрешение на чтение всех файлов не требуются.'} Руководство всегда доступно по значку информации.</p><h2>2. ${admin?'Настройка гостиницы':'Выбор номера'}</h2><p>${admin?'Роль admin может задать название и адрес в настройках. Guard видит рабочие разделы, но не меняет административные настройки и не получает административные отчёты. Для новой брони откройте подбор, задайте даты и выберите номер.':'На главной выберите даты, число гостей и категорию. Стандарт, комфорт и люкс доступны для 1–3 гостей. При категории «Все» и достаточном бюджете видны все подходящие свободные номера. Занятость и ремонт сохраняются.'}</p><h2>3. Автозаполнение и сохранение</h2><p>После выбора номера подставляются гостиница, адрес, категория, цена, даты и число ночей. Контакты гостя берутся из профиля. Измените их при необходимости и проверьте итог. Дата выезда не считается ночью проживания. Цена указана за номер, услуги учитываются отдельно. Сервер повторно проверяет даты и доступность при сохранении.</p><p>${admin?'Для гостя с аккаунтом выберите его в форме. Для гостя без аккаунта оставьте соответствующий вариант и заполните контакты. При необходимости отметьте заселение сегодня.':'После сохранения откроются бронь и счёт. В личном кабинете доступны только собственные записи.'} Кнопка «Повторить поездку» переносит категорию и число гостей в новый подбор; новые даты нужно проверить отдельно.</p><h2>4. ${admin?'Заселение, услуги и выезд':'Оплата и изменение поездки'}</h2><p>${admin?'В карточке проживания доступны разрешённые переходы статуса, услуги, ручной учёт оплаты и возврата. Перед выездом закройте счёт. После выезда или переселения комната требует уборки. В разделе уборки меняйте её состояние; ремонт требует предварительного переноса активных броней.':'До заселения можно изменить разрешённые параметры или отменить бронь. Если уже принята оплата или добавлены услуги, сначала обратитесь к персоналу для корректировки счёта.'}</p><p>СБП / QR — демонстрация без списания настоящих денег. Выберите сумму и способ, откройте учебную форму банка и задайте результат симуляции. Сервер не позволяет повторно учесть один и тот же успешный платёж.</p><h2>5. Общая база и уведомления</h2><p>Все устройства работают с базой одного сервера. Другой пользователь увидит изменения после обновления страницы или автоматической проверки каждые 15 секунд. ${admin?'Действия гостей приходят в уведомления администратора. Журнал фиксирует входы, изменения и отказы. Отчёт можно сохранить в CSV или через печать браузера в PDF.':'Контакты из профиля используются для будущих подстановок. Администратор видит действия, связанные с вашей бронью и оплатой.'}</p><h2>6. Домой и несохранённые формы</h2><p>Кнопка «Домой» есть в верхней панели и возвращает на главную своей роли. При несохранённом вводе сайт спрашивает подтверждение. Если хотите закончить редактирование, выберите «Остаться». Открытая форма не перезаписывается фоновым обновлением.</p><h2>7. Безопасность и восстановление</h2><p>После четырёх неверных попыток вход или PIN блокируется на 5 минут. Пароль чувствителен к регистру. Для восстановления PIN сначала подтвердите пароль, затем используйте сохранённый код. Новый код заменит предыдущий. Не передавайте пароль, PIN или recovery-код другим людям.</p><p>При работе на общем компьютере нажмите «Выйти из аккаунта». Для общих устройств используйте разные аккаунты и отдельные браузеры/профили. Не удаляйте файл базы data/hotel.sqlite: там хранятся записи локального сервера.</p><h2>8. Что перенесено из Android</h2><p>Оформление, роли, бронирования, расчёты, уведомления и руководства перенесены в веб-версию. Android Keystore и биометрия не имитируются; на сайте применяются серверные сессии, PIN и проверка прав в API. Браузерные разрешения выдаются самим браузером.</p></article>`}
function helpPage(){return `${head('Помощь всегда рядом','Руководство можно распечатать или сохранить в PDF.',btn('Печать / PDF','print','outline sm'))}<div class="card">${guideHtml(app.user.role!=='guest')}</div>`}
function renderPage(){const key=app.route.split('/')[0],page=$('#page');if(!page)return;stopCamera();const renderers={home:()=>app.user.role==='guest'?guestHome():dashboard(),rooms:()=>head('Найдём ваш номер','Все категории доступны для 1–3 гостей.')+'<div class="card">'+searchForm()+'</div><div id="room-results"></div>',bookings:bookingsPage,stay:()=>stayPage(app.route.slice(5)),notifications:notificationsPage,profile:profilePage,housekeeping:housekeepingPage,guests:guestsPage,calendar:calendarPage,reports:reportsPage,audit:auditPage,settings:settingsPage,labs:labsPage,tasks:tasksPage,notes:notesPage,security:securityPage,scanner:scannerPage,sync:syncPage,help:helpPage};page.innerHTML=(renderers[key]??renderers.home)();bindPage();if(key==='bookings')fillBookings();if(key==='rooms'||(key==='home'&&app.user.role==='guest'))fillAvailability()}
function submitForm(form,callback){form.onsubmit=async e=>{e.preventDefault();if(form.dataset.busy)return;const data=Object.fromEntries(new FormData(form));const controls=$$('button,input,select,textarea',form);form.dataset.busy='1';controls.forEach(c=>c.disabled=true);const error=$('.form-error',form);if(error)error.textContent='';try{await callback(data)}catch(err){if(error&&error.isConnected)error.textContent=err.message;else toast(err.message,true)}finally{delete form.dataset.busy;controls.forEach(c=>c.disabled=false)}}}
function bindPage(){const search=$('#search-form');if(search){search.onsubmit=e=>{e.preventDefault();captureFilter();fillAvailability()};search.elements.from.onchange=()=>{if(search.elements.to.value<=search.elements.from.value)search.elements.to.value=plus(search.elements.from.value,1);search.elements.to.min=plus(search.elements.from.value,1)}}
 const profile=$('#profile-form');if(profile){profile.oninput=()=>{app.dirty=true};submitForm(profile,async p=>{await action({kind:'profile.update',...p});app.dirty=false;await load();toast('Контакты сохранены')})}
 const hotel=$('#hotel-form');if(hotel){hotel.oninput=()=>{app.dirty=true};submitForm(hotel,async p=>{await action({kind:'hotel.update',...p});app.dirty=false;await load();toast('Данные гостиницы обновлены')})}
 const task=$('#task-form');if(task){task.oninput=()=>{app.dirty=true};submitForm(task,async p=>{await action({kind:'task.add',...p});app.dirty=false;await load();toast('Задача добавлена')})}
 const report=$('#report-form');if(report)submitForm(report,async p=>{app.report=await api('report?'+new URLSearchParams(p));renderPage()});
 const bs=$('#booking-search');if(bs)bs.oninput=e=>{app.query=e.target.value;fillBookings()};const as=$('#audit-search');if(as)as.onchange=e=>{app.query=e.target.value;renderPage()};
 const pass=$('#pass-form');if(pass)submitForm(pass,async p=>{const r=await action({kind:'pass.verify',...p});toast('Учебный пропуск подтверждён: '+r.person);await load()});
 const nf=$('#notes-file');if(nf)nf.onchange=async()=>{const file=nf.files[0];if(!file)return;try{if(file.size>60000)throw new Error('Импорт — не более 60 КБ');const notes=JSON.parse(await file.text());if(!Array.isArray(notes)||notes.length>100)throw new Error('Ожидается массив до 100 заметок');if(!await ask('Импорт заметок','Добавить записи из выбранного файла в ваши заметки?'))return;await action({kind:'notes.import',notes:notes.map(n=>({title:n.title,body:n.body}))});await load();toast('Заметки импортированы')}catch(e){toast(e.message,true)}}
}
function captureFilter(){const f=$('#search-form');if(!f)return;const p=Object.fromEntries(new FormData(f));Object.assign(app.filter,{from:p.from,to:p.to,people:Number(p.people),budget:Number(p.budget)})}
function contactFields(c){return `<div class="form-grid">${field('Имя гостя','name',c.name??'','text','required minlength="2" maxlength="100" autocomplete="name"')}${field('Телефон','phone',c.phone??'','tel','maxlength="30" autocomplete="tel"')}${field('Email','email',c.email??'','email','maxlength="120" autocomplete="email"')}<label class="field span2"><span>Пожелания</span><textarea name="wishes" maxlength="1000">${esc(c.wishes??'')}</textarea></label></div>`}
function bookRoom(id){const r=roomBy(id);if(!r)return;const staff=app.user.role!=='guest',guests=app.state.users.filter(u=>u.role==='guest'),me=staff?{name:'',phone:'',email:'',wishes:''}:app.user;
 modal('Бронирование №'+r.id,`<form id="booking-form" class="stack"><img class="modal-photo" src="./assets/${r.image}.jpg" alt="${r.category}"><div class="booking-summary"><strong>${esc(app.state.hotel.name)}</strong><p>${esc(app.state.hotel.address)}</p><h3>№${r.id} · ${r.category}</h3><div id="booking-total"></div><small>${money(r.price)} за номер / ночь. Услуги — отдельно.</small></div><div class="form-grid">${field('Заезд','arrival',app.filter.from,'date',`required min="${app.today}"`)}${field('Выезд','departure',app.filter.to,'date','required')}${select('Количество гостей','people',[[1,'1 гость'],[2,'2 гостя'],[3,'3 гостя']],app.filter.people)}</div>${staff?select('Гость с аккаунтом','customerId',[['','Новый гость без личного аккаунта'],...guests.map(g=>[g.id,g.name+' · '+g.login])],''):''}${contactFields(me)}${staff?'<label class="check-row"><input name="walkIn" type="checkbox"> Заселить сразу (заезд сегодня)</label>':''}<div class="info">Доступность и стоимость повторно проверяются сервером. Контакты сохраняются вместе с бронью.</div><div class="error form-error"></div><button type="submit" class="btn block">Подтвердить бронирование</button></form>`);
 const f=$('#booking-form');const total=()=>{const n=(Date.parse(f.elements.departure.value)-Date.parse(f.elements.arrival.value))/86400000;$('#booking-total').innerHTML=Number.isFinite(n)&&n>0?`<p>${n} ноч. · ${f.elements.people.value} гост.</p><div class="sum">${money(n*r.price)}</div>`:'<p class="error">Выберите даты проживания</p>'};f.oninput=()=>{app.modalDirty=true;total()};f.elements.arrival.onchange=()=>{if(f.elements.departure.value<=f.elements.arrival.value)f.elements.departure.value=plus(f.elements.arrival.value,1);f.elements.departure.min=plus(f.elements.arrival.value,1);total()};
 if(staff){f.elements.customerId.onchange=()=>{const g=guests.find(g=>g.id===f.elements.customerId.value);if(g)for(const k of ['name','phone','email','wishes'])f.elements[k].value=g[k]??'';app.modalDirty=true};f.elements.walkIn.onchange=()=>{if(f.elements.walkIn.checked){f.elements.arrival.value=app.today;if(f.elements.departure.value<=app.today)f.elements.departure.value=plus(app.today,1)}f.elements.arrival.readOnly=f.elements.walkIn.checked;total()}}
 total();submitForm(f,async p=>{const result=await action({kind:'booking.create',...p,roomId:r.id,people:Number(p.people),walkIn:p.walkIn==='on'});await closeModal(true);await load(true);await navigate('stay/'+result.id);toast('Бронирование сохранено')})
}
function editBooking(id){const b=app.state.bookings.find(b=>b.id===id);if(!b)return;modal('Изменить проживание',`<form id="amend-form" class="stack">${select('Номер','roomId',app.state.rooms.map(r=>[r.id,'№'+r.id+' · '+r.category+' · '+money(r.price)]),b.roomId)}<div class="form-grid">${field('Заезд','arrival',b.arrival,'date',b.status==='Заселён'?'required readonly':`required min="${app.today}"`)}${field('Выезд','departure',b.departure,'date','required')}${select('Гости','people',[1,2,3],b.people)}</div><p class="muted">Стоимость пересчитывается по выбранной категории за всё проживание. Пересечения и переплата проверяются сервером.</p><div class="error form-error"></div><button class="btn" type="submit">Сохранить изменения</button></form>`);submitForm($('#amend-form'),async p=>{await action({kind:'booking.amend',id,...p,roomId:Number(p.roomId),people:Number(p.people)});await closeModal(true);await load();toast('Бронь обновлена')})}
function careDialog(id){const r=roomBy(id),c=app.state.care.find(c=>c.roomId===r.id)??{status:'Готов',note:''};modal('Состояние номера '+id,`<form id="care-form" class="stack">${select('Состояние','status',['Готов','Требуется уборка','Уборка','Ремонт'],c.status)}<label class="field"><span>Примечание</span><textarea name="note" maxlength="500">${esc(c.note)}</textarea></label><div class="error form-error"></div><button class="btn" type="submit">Сохранить состояние</button></form>`);submitForm($('#care-form'),async p=>{await action({kind:'room.care',roomId:Number(id),...p});await closeModal(true);await load();toast('Состояние номера обновлено')})}
function serviceDialog(id){modal('Добавить услугу',`<form id="service-form" class="stack">${field('Название услуги','title','Завтрак','text','required minlength="2" maxlength="100"')}<div class="form-grid">${field('Количество','quantity',1,'number','required min="1" max="100"')}${field('Цена за единицу, ₽','price',500,'number','required min="1" max="1000000"')}</div><div class="error form-error"></div><button class="btn" type="submit">Добавить в счёт</button></form>`);submitForm($('#service-form'),async p=>{await action({kind:'service.add',id,...p});await closeModal(true);await load();toast('Услуга добавлена')})}
function manualPayment(id,refund=false){const b=app.state.bookings.find(b=>b.id===id),i=invoice(b);modal(refund?'Учесть возврат':'Учесть оплату',`<form id="payment-form" class="stack"><div class="info">Ручной учёт в гостинице. Банковского списания или возврата не происходит.</div>${field('Сумма, ₽','amount',refund?i.paid:i.balance,'number',`required min="1" max="${refund?i.paid:i.balance}"`)}${select('Способ учёта','method',['Наличные','Карта (учёт)','Перевод (учёт)'],'Наличные')}<div class="error form-error"></div><button class="btn" type="submit">${refund?'Сохранить возврат':'Сохранить оплату'}</button></form>`);submitForm($('#payment-form'),async p=>{await action({kind:'payment.add',id,...p,refund});await closeModal(true);await load();toast(refund?'Возврат учтён':'Оплата учтена')})}
function demoPayment(id){const b=app.state.bookings.find(b=>b.id===id),i=invoice(b);modal('Учебная платёжная форма',`<form id="demo-form" class="stack"><div class="row between"><span class="label">HOTEL PAY · ДЕМО</span>${badge('Без списания денег')}</div><h3>${esc(app.state.hotel.name)} · №${b.roomId}</h3>${field('Сумма к оплате, ₽','amount',i.balance,'number',`required min="1" max="${i.balance}"`)}${select('Способ','method',['СБП','QR-код'],'СБП')}<div class="info">Это симуляция. Не вводите настоящие банковские реквизиты. Результат будет сохранён в общем счёте гостиницы.</div><div class="error form-error"></div><button class="btn" type="submit">Открыть учебный платёж</button></form>`);submitForm($('#demo-form'),async p=>{const r=await action({kind:'checkout.start',id,...p});await load(true);app.modalDirty=false;checkoutView(r.id)})}
function qrSvg(payload){if(typeof window.qrcode!=='function')return '<div class="code">'+esc(payload)+'</div>';const q=window.qrcode(0,'M');q.addData(payload);q.make();return q.createSvgTag({scalable:true,margin:3})}
function checkoutView(id,stage='qr'){const c=app.state.checkouts.find(x=>x.id===id);if(!c)return toast('Платёж не найден',true);const done=c.status!=='PENDING';modal(done?'Результат учебной оплаты':'Оплата '+c.method,`<div class="stack"><div class="row between"><span class="label">HOTEL PAY · ДЕМО</span>${badge(c.status)}</div><div class="payment-amount">${money(c.amount)}</div><p class="muted" style="text-align:center">${esc(app.state.hotel.name)} · заказ ${c.id.slice(0,8)}</p>${done?`<div class="info ${c.status==='SUCCESS'?'success':''}">${c.status==='SUCCESS'?'Учебная оплата успешно записана в счёт. Реальные деньги не списывались.':'Платёж не проведён. Счёт не изменился.'}</div>${btn('Вернуться к бронированию','payment-return','block',`data-id="${c.bookingId}"`)}`:stage==='qr'?`<div class="qr">${qrSvg('HOTEL-DEMO|NO-REAL-PAYMENT|order='+c.id+'|amount='+c.amount+'|RUB')}</div><p class="muted">QR содержит учебный текст, а не банковскую ссылку. Заказ действует 5 минут. Для демонстрации откройте симулятор банка.</p>${btn('Открыть симулятор банка','bank-demo','block',`data-id="${id}"`)}${btn('Отменить платёж','checkout-finish','outline block',`data-id="${id}" data-result="CANCELLED"`)}`:`<div class="payment-method"><div>${icon('card')} Учебный банк<br><small>Выберите результат симуляции</small></div>${icon('shield')}</div>${btn('Подтвердить успешную оплату','checkout-finish','block',`data-id="${id}" data-result="SUCCESS"`)}${btn('Симулировать отказ банка','checkout-finish','outline block',`data-id="${id}" data-result="FAILED"`)}${btn('Отмена','checkout-finish','danger block',`data-id="${id}" data-result="CANCELLED"`)}`}</div>`)}
function guestEdit(id,booking=false){const g=booking?app.state.bookings.find(x=>x.id===id):app.state.users.find(x=>x.id===id);if(!g)return;modal('Контакты гостя',`<form id="guest-form" class="stack">${contactFields(booking?{...g,name:g.guest}:g)}<div class="error form-error"></div><button class="btn" type="submit">Сохранить контакты</button></form>`);submitForm($('#guest-form'),async p=>{await action({kind:booking?'booking.contact':'guest.update',id,...p});await closeModal(true);await load();toast('Контакты сохранены')})}
function noteEdit(id){const n=app.state.notes.find(x=>x.id===id)??{title:'',body:''};modal(id?'Заметка смены':'Новая заметка',`<form id="note-form" class="stack">${field('Заголовок','title',n.title,'text','required maxlength="200"')}<label class="field"><span>Текст заметки</span><textarea name="body" rows="8" maxlength="20000">${esc(n.body)}</textarea></label><div class="error form-error"></div><button class="btn" type="submit">Сохранить заметку</button></form>`);submitForm($('#note-form'),async p=>{await action({kind:'note.save',...(id?{id}:{}),...p});await closeModal(true);await load();toast('Заметка сохранена')})}
async function cameraStart(){try{if(!navigator.mediaDevices?.getUserMedia)throw new Error('Для камеры требуется HTTPS или localhost. Используйте ручной ввод.');stopCamera();app.media=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'},audio:false});const v=$('#scan-video');if(!v){stopCamera();return}v.hidden=false;v.srcObject=app.media;await v.play();if(!('BarcodeDetector'in window)){toast('Камера включена, но автоматическое распознавание недоступно в этом браузере. Используйте ручной ввод.');return}const detector=new window.BarcodeDetector({formats:['qr_code']});let running=false;app.scanTimer=setInterval(async()=>{if(running||!v.videoWidth)return;running=true;try{const codes=await detector.detect(v);if(codes.length){$('#pass-form input[name=code]').value=codes[0].rawValue;stopCamera();toast('Код считан. Нажмите «Проверить на сервере».')}}catch{}finally{running=false}},700)}catch(e){toast(e.name==='NotAllowedError'?'Разрешите доступ к камере в настройках сайта или используйте ручной ввод.':e.message,true)}}
function saveFile(name,contents,type='application/json'){const url=URL.createObjectURL(new Blob([contents],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000)}
function csvCell(v){let s=String(v??'');if(typeof v!=='number'&&/^[=+@-]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'}
async function exportData(){let r;try{r=await api('export')}catch(e){if(e.status===428){await pinPrompt();r=await api('export')}else throw e}saveFile('HotelManager-export-'+app.today+'.json',JSON.stringify(r,null,2));toast('Экспорт сохранён. Он может содержать данные гостей.')}
async function handleClick(e){const node=e.target.closest('[data-act],[data-nav],[data-demo],[data-category],[data-status-filter]');if(!node)return;

 if(node.dataset.nav){e.preventDefault();await navigate(node.dataset.nav);return}
 if(node.dataset.category){captureFilter();app.filter.category=node.dataset.category;renderPage();return}
 if(node.dataset.statusFilter){app.bookingFilter=node.dataset.statusFilter;renderPage();return}
 const act=node.dataset.act,id=node.dataset.id;try{
 switch(act){
 case 'theme':setTheme();break;
 case 'password-show':{const input=$('#auth-form input[name=password]');input.type=input.type==='password'?'text':'password';node.setAttribute('aria-label',input.type==='password'?'Показать пароль':'Скрыть пароль');break}
 case 'login':loginView();break;case 'register':loginView(true);break;
 case 'logout':if(app.dirty&&!await ask('Выйти без сохранения?','Изменения страницы не сохранены. Выйти из аккаунта?'))return;if(!await closeModal())return;await api('logout','POST',{});app.user=null;app.state=null;app.route='home';app.trail=[];loginView();break;
 case 'recover':recoveryFlow();break;
 case 'recovery-done':await closeModal(true);await load();break;
 case 'welcome-done':await finishWelcome();break;case 'welcome-camera':await finishWelcome(true);break;
 case 'welcome-guide':modal('Руководство',guideHtml(app.user.role!=='guest'),btn('Вернуться к знакомству','welcome-back','outline'),false);break;
 case 'welcome-back':welcome();break;
 case 'close-modal':await closeModal();break;
 case 'home':await navigate('home',true);break;
 case 'new-booking':await navigate('rooms');break;case 'to-bookings':await navigate('bookings');break;
 case 'profile-link':await navigate('profile');break;case 'help-link':await navigate('help');break;
 case 'refresh':if(app.dirty){toast('Сначала сохраните или отмените редактирование');return}await load();toast('Данные обновлены');break;
 case 'menu':$('#sidebar').classList.toggle('open');break;case 'menu-close':$('#sidebar').classList.remove('open');break;
 case 'room-book':captureFilter();bookRoom(Number(id));break;
 case 'stay':await navigate('stay/'+id);break;
 case 'amend':editBooking(id);break;
 case 'repeat':{const b=app.state.bookings.find(b=>b.id===id);app.filter={...app.filter,from:app.today,to:plus(app.today,1),people:b.people,category:roomBy(b.roomId).category};await navigate('rooms');toast('Категория и гости подставлены. Проверьте новые даты.');break}
 case 'status':if(!await ask('Подтвердите изменение',`Изменить статус бронирования на «${node.dataset.target}»?`))return;await action({kind:'booking.status',id,status:node.dataset.target});await load();toast('Статус обновлён');break;
 case 'care':careDialog(Number(id));break;
 case 'service':serviceDialog(id);break;
 case 'service-remove':if(!await ask('Удалить услугу?','Услуга будет удалена из учебного счёта.'))return;await action({kind:'service.remove',id});await load();toast('Услуга удалена');break;
 case 'manual-pay':manualPayment(id);break;case 'refund':manualPayment(id,true);break;
 case 'demo-pay':demoPayment(id);break;case 'bank-demo':checkoutView(id,'bank');break;
 case 'checkout-finish':{node.disabled=true;try{const result=await action({kind:'checkout.finish',id,status:node.dataset.result});await load(true);checkoutView(id);toast(result.status==='SUCCESS'?'Учебная оплата записана':'Платёж завершён: '+result.status)}finally{node.disabled=false}break}
 case 'payment-return':await closeModal(true);await navigate('stay/'+id);break;
 case 'guest-edit':guestEdit(id);break;case 'booking-contact':guestEdit(id,true);break;
 case 'notice-read':await action({kind:'notice.read'});await load();toast('Уведомления прочитаны');break;
 case 'calendar-prev':app.calendarStart=plus(app.calendarStart??app.today,-7);renderPage();break;case 'calendar-next':app.calendarStart=plus(app.calendarStart??app.today,7);renderPage();break;
 case 'task-toggle':await action({kind:'task.toggle',id});await load();break;case 'task-delete':await action({kind:'task.delete',id});await load();break;
 case 'note-new':noteEdit();break;case 'note-edit':noteEdit(id);break;
 case 'note-delete':if(!await ask('Удалить заметку?','Запись будет удалена с сервера.'))return;await action({kind:'note.delete',id});await load();break;
 case 'notes-import':$('#notes-file').click();break;
 case 'notes-export':saveFile('HotelManager-notes.json',JSON.stringify(app.state.notes.map(({title,body})=>({title,body})),null,2));break;
 case 'pass-qr':modal('Учебный QR-пропуск',`<div class="stack"><div class="qr">${qrSvg('HOTEL:'+app.user.role)}</div><div class="code">HOTEL:${esc(app.user.role)}</div><p class="muted">Пример для лабораторной проверки, не реальный пропуск.</p></div>`);break;
 case 'camera-start':await cameraStart();break;case 'camera-stop':stopCamera();if($('#scan-video'))$('#scan-video').hidden=true;break;
 case 'pin-check':await pinPrompt();toast('PIN подтверждён');break;
 case 'print':window.print();break;
 case 'report-csv':if(!app.report){toast('Сначала сформируйте отчёт');return}saveFile('HotelManager-report-'+app.today+'.csv','\ufeff'+[['Гость','Номер','Заезд','Выезд','Гости','Статус','Начислено','Принято','Остаток'],...app.report.rows.map(b=>[b.guest,b.roomId,b.arrival,b.departure,b.people,b.status,b.total,b.paid,b.balance])].map(row=>row.map(csvCell).join(';')).join('\r\n'),'text/csv;charset=utf-8');break;
 case 'export':await exportData();break;
 }
 }catch(err){toast(err.message,true);if(err.status===401&&app.user?.verified){await closeModal(true);await load()}}
}
document.addEventListener('click',e=>{handleClick(e).catch(err=>toast(err.message,true))});
window.addEventListener('beforeunload',e=>{if(app.dirty||app.modalDirty){e.preventDefault();e.returnValue=''}});
window.addEventListener('pagehide',stopCamera);
const narrow=matchMedia('(max-width:700px)');narrow.addEventListener('change',()=>{if(app.user?.verified&&app.route==='bookings'&&!$('#modal').open)renderPage()});
setInterval(async()=>{if(!app.user?.verified||document.hidden)return;try{const old=app.state?.revision;await load(true);if(!app.user?.verified){await closeModal(true);renderShellOrAuth();return}if(app.state.revision!==old&&!app.dirty&&!$('#modal').open&&!app.media&&!document.activeElement?.matches('input,textarea,select'))renderShell()}catch(e){if(e.status===401){await closeModal(true);app.user=null;app.state=null;renderShellOrAuth()}}},15000);
load().catch(e=>{$('#app').innerHTML=`<section class="card error-page stack">${brand()}<h1>Нет подключения к серверу</h1><p>${esc(e.message)}</p><div class="info">Этот сайт использует общую базу. На компьютере запустите <strong>node server.mjs</strong>, затем откройте <strong>http://localhost:3000</strong>. Двойной щелчок по index.html не запускает сервер.</div><button class="btn" id="retry-load">Повторить подключение</button></section>`;$('#retry-load').onclick=()=>location.reload()});
